sketches.source:
setcpm(140/4)

// One break, sealed tight: scrambled in some bars, a moving quarter hurried in every bar
const brk = s("bd ~ [~ bd] ~ sd ~ bd sd")
drums: brk.someCyclesBy(.5, x => x.scramble(8)).chunk(4, x => x.hurry(2))
  .crush("<16 8 6 4>").seed("seal").gain(.6)

// Hats lean right; a seeded coin flip throws some of them into the left ear
hats: s("hh*16").hpf(7000).ild(10).earswap(irand(2).segment(16)).seed("wrap").gain(.24)

// A bass ring-modulated into a gargle, swinging between the ears on delays under a millisecond
bass: note("c2 ~ c2 eb2 ~ c2 gb2 ~").s("sawtooth").ringmod(sine.range(30, 300).slow(4)).ringmix(.5)
  .itd(sine.range(-.6, .6).slow(2)).lpf(1100).decay(.15).sustain(.3).release(.05).gain(.38)

// Frequency-shifted bells with no key left, each struck from a random place around your head
bells: note("<c5 gb5 a4 eb5>").s("sine").fm(4).fmh(1.41).fshift("<0 37 -113 250>")
  .azimuth(rand.range(-180, 180)).distance(2).decay(.4).sustain(0).seed("bell").gain(.14)

setcpm(110/4)

// Bubble wrap: pops at random places all around your head, some close, some far
pops: s("click*16?0.6").speed(rand.range(.6, 2))
  .azimuth(rand.range(-180, 180)).elevation(rand.range(-30, 60)).distance(rand.range(.6, 3))
  .seed("pop").gain(.3)

// The roll unspooling: identical noise in both ears, a point, opening bar by bar into a wash
unroll: s("pink").icorr("<1 .6 .3 .05>").hpf(saw.range(400, 5000)).gain(.05)

// A cheerful tune whose ears drift apart in cents: 4, 12, 30, then a seasick 60
tune: n("0 2 4 7 4 2 0 -1").scale("C:major").transpose(12).s("triangle").timbre("glass")
  .earsh("<4 12 30 60>").decay(.2).sustain(0).delay(.3).delaytime(3/16).gain(.2)

// The kick and bass stay in the middle, pretending nothing is wrong
kick: s("bd ~ [~ bd] ~").shape(.2).gain(.6)
bass: note("<c2 a1 f1 g1>").struct("x ~ x ~").s("sine").shape(.2).decay(.3).sustain(.3).gain(.4)

setcpm(220/4)

// On the last bar of every eight, the whole band rushes twice as fast
const polka = (x) => x.lastOf(8, y => y.hurry(2))

// Oom-pah split by partials: each ear hears every other harmonic of the accordion
oompah: note("<[c2 [e3,g3] g1 [e3,g3]] [g1 [d3,f3,b3] d2 [d3,f3,b3]]>")
  .s("sawtooth").timbre("reed").earsplit("harmonics").vowel("a").lpf(2000)
  .decay(.15).sustain(.3).release(.05).polka().gain(.3)

// The tune, far too cheerful, hopping from ear to ear on every other note
tune: note("<[e5 g5 e5 c5] [d5 f5 d5 b4] [e5 g5 c6 g5] [d5@2 c5@2]>")
  .s("sawtooth").timbre("reed").vowel("e").lpf(3000).attack(.01).sustain(.6).release(.05)
  .ild(9).earswap("0 1 0 1").polka().gain(.22)

drums: s("bd sd bd sd, hh*8").polka().gain(.45)

// Meanwhile an air-raid siren circles high overhead
siren: freq(sine.range(500, 1100).slow(2).segment(16)).s("sine").mono(1).glide(.12)
  .azimuth(saw.range(-180, 180).slow(4)).elevation(50).distance(4).posglide(.2)
  .attack(.01).sustain(1).release(.05).gain(.06)

// The rumble starts as one point in your head and opens into a wash over eight bars
rumble: s("brown*4").icorr(isaw.slow(8)).lpf(saw.range(100, 1200).slow(8))
  .gain(saw.range(.02, .2).slow(8)).attack(.05).release(.1)

// And a drone whose phase between the ears spins faster as the end approaches
spin: note("[c2,g2]").s("sine").irate("<.5 .5 1 1 2 2 2.9 2.9>").gain(.1)

setcpm(140/4)

// Seven generations of rewriting, hopping between the ears on the Thue-Morse sequence
melody: n(lsys("0", "0=0 3, 3=5 0, 5=3", 7, 4)).scale("C:phrygian dominant").transpose(12)
  .s("square").pw(.2).ild(9).earswap(ints("thuemorse", 16)).decay(.08).sustain(0)
  .delay(.25).delaytime(3/16).gain(.16)

// Kicks and snares from sieves of residue classes, kept in the middle
kick: s("bd").struct(sieve("3@0 | 5@1", 16)).shape(.3).gain(.65)
snare: s("sd").struct(sieve("7@3 | 11@6", 16)).gain(.4)

// The van der Corput sequence spreads the hats evenly all the way around your head
hats: s("hh*16").hpf(7000).azimuth(ints("vdc", 16).range(-180, 180)).distance(1.5).gain(.22)

// Toms on the prime steps, stepping between five places in front of you by the ruler sequence
toms: s("lt").struct(ints("prime", 16)).azimuth(ints("ruler", 16).mod(5).mul(45).sub(90)).gain(.28)

// The bass counts Collatz steps; the left ear's filter wanders, the right ear's holds still
bass: n(ints("collatz", 4).mod(7)).scale("C:phrygian dominant").octave(-1)
  .s("sawtooth").lcutoff(perlin.range(300, 2400)).rcutoff(900)
  .decay(.15).sustain(.3).gain(.32)

setcpm(100/4)

// One figure at five speeds, shifted so every copy reaches the start together at bar 16
// Each note sounds from a random place in front of and beside you
soup: n("0 3 5 7 10 7 5 3").scale("C:minor pentatonic").transpose(12)
  .converge(16, 1, 7/6, 5/4, 4/3, 3/2)
  .s("triangle").timbre("glass").decay(.15).sustain(0)
  .azimuth(rand.range(-150, 150)).distance(2).seed("soup").room(.4).gain(.1)

// Two drummers who disagree: one on your left holds still, the one on your right slips a sixteenth each bar
drummer1: s("bd ~ sd ~ bd bd sd ~, hh*8").azimuth(-90).distance(2).gain(.38)
drummer2: s("bd ~ sd ~ bd bd sd ~, hh*8").phase(1/16).azimuth(90).distance(2).gain(.34)

// A crash high above you on the meeting point, every sixteen bars
crash: s("<cr ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~>").elevation(60).distance(3).room(.6).gain(.4)

// The bass stays straight ahead
bass: note("<c2 eb2 f2 g2>").s("sine").shape(.2).decay(.4).sustain(.4).release(.2).gain(.4)

setcpm(120/4)

// The off-beats are white noise hiding a hook between the ears: each ear alone hears only hiss
ghost: s("[~ white]*4").dichotic("<[440 523 659 523] [440 523 784 659] [349 440 523 440] [392 494 587 494]>")
  .dichoticq(30).attack(.005).sustain(1).release(.05).gain(.14)

// The hook on a frozen, smeared synth, once every four bars, so you know what to listen for
hint: note("<[~ a4 ~ c5 ~ e5 ~ c5] ~ ~ ~>").s("square").pw(.3).spectral("freeze").samount(.6)
  .decay(.15).sustain(.2).release(.1).gain(.08)

// A pad that steps from the centre of your head to all around it, and nearly vanishes in mono
pad: note("<[a3,c4,e4] [f3,a3,c4] [d3,f3,a3] [e3,g#3,b3]>").s("sawtooth").unison(3).detune(.2)
  .iphase("<0 90 180 90>").lpf(1400).attack(.5).release(1).gain(.12)

// A centred kick and bass
kick: s("bd*4").shape(.2).gain(.75)
bass: note("<a1 f1 d1 e1>").struct("~ x ~ x ~ x ~ x").s("sawtooth").lpf(600).decay(.15).sustain(.3).gain(.4)

// Clicks crushed to four bits, drifting slowly around the room
clicks: s("click*8?0.4").crush(4).azimuth(sine.range(-150, 150).slow(8))
  .distance(3).posglide(.4).seed("ghost").gain(.12)

setcpm(110/4)

// A saw bass with something to say, straight ahead: talk puts a syllable track on it
bass: note("c2 c2 eb2 c2 g1 c2 bb1 c2").s("sawtooth")
  .syl("<[wa wa wo wi] [ya ya yo yu] [ba ba bo bi] [na na no neng]>").talk(1)
  .lpf(2400).decay(.2).sustain(.4).gain(.35)

// A crunchy, swung breakfast beat
drums: s("bd ~ [~ bd] ~, ~ sd ~ sd, hh*8").swing(4).crush(10).gain(.45)

// The radio mutters on your right, half hidden behind the bread bin
radio: s("whisper*8?0.5").syl("<sha ko ta ri>").crush(4).hpf(1000)
  .azimuth(70).distance(3).occlude(.4).seed("static").gain(.14)

// The kettle on your left works up to a whistle that throbs five times a second
kettle: note("<~ ~ ~ c7>").s("sine").isochronic(5).isodepth(.6)
  .attack(1).sustain(1).release(.5).azimuth(-70).distance(3).gain(.05)

// The toaster pops right behind you
pop: s("<~ ~ ~ [~ ~ ~ click]>").speed(.5).azimuth(180).distance(1).gain(.5)

// The announcement, from directly above: toast is ready
robot: note("<c4 eb4 g4 bb4>").s("voice").syl("<toast is re_a dee>").voicetype("bass")
  .spectral("robot").samount(.7).mono(1).vglide(.04).elevation(60).distance(1.5).gain(.26)

setcpm(60/4)

// One innocent piano phrase
const phrase = n("<[0 2 4 7] [5 4 2 0] [3 5 7 9] [7@2 4 2]>").scale("F:major").transpose(12)
  .s("triangle").timbre("soft").decay(.6).sustain(.1).release(.6)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("<f2 d2 bb1 c2>").s("sine").binaural(2).attack(3).sustain(1).release(4).gain(.24)

// Plain, frozen into a smear, blurred into fog, then combed into metal at 110 Hz
piano: form("A@4 B@4 C@4 D@4", phrase,
  phrase.spectral("freeze").samount(.9),
  phrase.spectral("blur").samount(.8),
  phrase.spectral("comb").scomb(110).samount(.7)).room(.5).gain(.24)

// The air of the room: unrelated noise in each ear, wide and all around
air: s("pink").slow(8).icorr(.1).hpf(800).lpf(4000).gain(.025)

// A clock ticking somewhere behind you
clock: s("tick ~ tick ~").azimuth(170).distance(4).gain(.05)
